use std::os::unix::process::CommandExt;
use std::process::Command;

Command::new("/usr/local/bin/job")
    .uid(65534)                 // also calls setgroups(0, NULL): no stray groups
    .gid(65534)
    .spawn()?;                  // the child starts with exactly this authority

// in-process: authority is the handle you hold, not a global to reach for
fn total(repo: &dyn ReadOnlyRepo) -> u64 { repo.total() }
